window.terminalShaderSources={vertex:"\n    attribute vec2 aPosition;\n    varying vec2 vUv;\n\n    void main() {\n      vUv = aPosition * 0.5 + 0.5;\n      gl_Position = vec4(aPosition, 0.0, 1.0);\n    }\n  ",fragment:"\n    precision mediump float;\n\n    varying vec2 vUv;\n\n    uniform vec2 uResolution;\n    uniform float uTime;\n    uniform float uScale;\n    uniform float uDigitSize;\n    uniform float uNoiseAmp;\n    uniform float uGlitchAmount;\n    uniform float uScanlineIntensity;\n    uniform float uBrightness;\n    uniform float uCurvature;\n    uniform vec3 uOverlayColor;\n    uniform float uOverlayAmount;\n\n    float time;\n\n    float hash21(vec2 p) {\n      p = fract(p * 234.56);\n      p += dot(p, p + 34.56);\n      return fract(p.x * p.y);\n    }\n\n    float noise(vec2 p) {\n      return sin(p.x * 10.0) * sin(p.y * (3.0 + sin(time * 0.090909))) + 0.2;\n    }\n\n    mat2 rotate(float angle) {\n      float c = cos(angle);\n      float s = sin(angle);\n      return mat2(c, -s, s, c);\n    }\n\n    float fbm(vec2 p) {\n      p *= 1.1;\n      float f = 0.0;\n      float amp = 0.5 * uNoiseAmp;\n\n      mat2 modify0 = rotate(time * 0.02);\n      f += amp * noise(p);\n      p = modify0 * p * 2.0;\n      amp *= 0.454545;\n\n      mat2 modify1 = rotate(time * 0.02);\n      f += amp * noise(p);\n      p = modify1 * p * 2.0;\n      amp *= 0.454545;\n\n      mat2 modify2 = rotate(time * 0.08);\n      f += amp * noise(p);\n\n      return f;\n    }\n\n    float pattern(vec2 p, out vec2 q, out vec2 r) {\n      vec2 offset1 = vec2(1.0);\n      vec2 offset0 = vec2(0.0);\n      mat2 rot01 = rotate(0.1 * time);\n      mat2 rot1 = rotate(0.1);\n\n      q = vec2(fbm(p + offset1), fbm(rot01 * p + offset1));\n      r = vec2(fbm(rot1 * q + offset0), fbm(q + offset0));\n      return fbm(p + r);\n    }\n\n    vec3 rainbow(vec2 uv) {\n      float t = uv.x * 0.5 + uTime * 0.02;\n      return 0.5 + 0.5 * cos(6.283185 * (t + vec3(0.0, 0.3333, 0.6666)));\n    }\n\n    float digit(vec2 p) {\n      vec2 grid = vec2(2.0, 1.0) * 15.0;\n      vec2 s = floor(p * grid) / grid;\n      p = p * grid;\n\n      vec2 q;\n      vec2 r;\n      float intensity = pattern(s * 0.1, q, r) * 1.3 - 0.03;\n      intensity += hash21(s + floor(time * 3.0)) * 0.2;\n\n      p = fract(p);\n      p *= uDigitSize;\n\n      float px5 = p.x * 5.0;\n      float py5 = (1.0 - p.y) * 5.0;\n      float x = fract(px5);\n      float y = fract(py5);\n\n      float i = floor(py5) - 2.0;\n      float j = floor(px5) - 2.0;\n      float n = i * i + j * j;\n      float f = n * 0.0625;\n\n      float isOn = step(0.1, intensity - f);\n      float brightness = isOn * (0.2 + y * 0.8) * (0.75 + x * 0.25);\n\n      return step(0.0, p.x) * step(p.x, 1.0) * step(0.0, p.y) * step(p.y, 1.0) * brightness;\n    }\n\n    float onOff(float a, float b, float c) {\n      return step(c, sin(time * 3.0 + a * cos(time * b)));\n    }\n\n    float displace(vec2 look) {\n      float y = look.y - mod(time * 0.75, 1.0);\n      float window = 1.0 / (1.0 + 50.0 * y * y);\n      return sin(look.y * 20.0 + time * 3.0) * 0.0125 * onOff(4.0, 2.0, 0.8) * (1.0 + cos(time * 180.0)) * window;\n    }\n\n    vec3 getColor(vec2 p) {\n      float bar = step(mod(p.y + time * 60.0, 1.0), 0.2) * 0.4 + 1.0;\n      bar *= uScanlineIntensity;\n\n      float displacement = displace(p);\n      p.x += displacement * uGlitchAmount;\n\n      float middle = digit(p);\n\n      const float off = 0.002;\n      float sum = digit(p + vec2(-off, -off)) + digit(p + vec2(0.0, -off)) + digit(p + vec2(off, -off)) +\n                  digit(p + vec2(-off, 0.0)) + digit(p + vec2(0.0, 0.0)) + digit(p + vec2(off, 0.0)) +\n                  digit(p + vec2(-off, off)) + digit(p + vec2(0.0, off)) + digit(p + vec2(off, off));\n\n      return vec3(0.9) * middle + sum * 0.1 * vec3(1.0) * bar;\n    }\n\n    vec2 barrel(vec2 uv) {\n      vec2 c = uv * 2.0 - 1.0;\n      float r2 = dot(c, c);\n      c *= 1.0 + uCurvature * r2;\n      return c * 0.5 + 0.5;\n    }\n\n    void main() {\n      time = uTime * 0.333333;\n      vec2 uv = barrel(vUv);\n      vec2 aspect = vec2((uResolution.x / uResolution.y) / 2.0, 1.0);\n      vec2 p = ((uv - 0.5) * aspect + 0.5) * uScale;\n      vec3 col = getColor(p);\n      col *= vec3(0.86, 0.91, 0.84);\n      vec3 rainbowOverlay = mix(uOverlayColor, rainbow(vUv), 0.85);\n      col = mix(col, col * rainbowOverlay, uOverlayAmount);\n      float saturation = 0.35;\n      float luminance = dot(col, vec3(0.299, 0.587, 0.114));\n      col = mix(vec3(luminance), col, saturation);\n      col *= uBrightness;\n\n      float rnd = hash21(gl_FragCoord.xy);\n      col += (rnd - 0.5) * 0.012;\n\n      gl_FragColor = vec4(col, max(max(col.r, col.g), col.b));\n    }\n  "};